PRIORITY_KEYWORDS = {
    'cyberpunk':       ['cyberpunk', 'hacker', 'megacorp', 'cyberspace', 'netrunner'],
    'xianxia':         ['xianxia', 'cultivation', 'immortal', 'wuxia'],
    'xuanhuan':        ['xuanhuan', 'profound', 'martial continent'],
    'cthulhu':         ['cthulhu', 'lovecraft', 'eldritch'],
    'magical_realism': ['magical realism', 'garcia marquez', 'murakami'],
    'japanese_horror': ['j-horror', 'onryo'],
    'isekai':          ['isekai', 'transmigration'],
}

def _detect_type(dna):
    text = " ".join([dna.get("overall_mood",""), dna.get("rhythm",""),
                     dna.get("music_direction",""), dna.get("setting",""),
                     " ".join(dna.get("themes",[]))]).lower()
    for genre, kws in PRIORITY_KEYWORDS.items():
        if any(kw in text for kw in kws):
            return genre
    best, best_n = "default", 0
    for genre, kws in KEYWORDS.items():
        n = sum(1 for kw in kws if kw in text)
        if n > best_n: best_n, best = n, genre
    return best

def get_scene_html(dna, lang="en"):
    from core.strings import STRINGS
    T = STRINGS.get(lang, STRINGS["en"])
    if not dna:
        return SCENES["golden_dusk"]
    family = TYPE_TO_FAMILY.get(_detect_type(dna), "golden_dusk")
    html = SCENES[family]
    html = html.replace("body{width:100%", "body{position:relative;width:100%")
    overlay = (
        '<div style="position:absolute;bottom:44px;left:32px;z-index:10;pointer-events:none;">'
        '<div style="font-family:Georgia,serif;font-size:30px;font-weight:700;'
        'color:rgba(225,210,180,0.92);letter-spacing:1px;'
        'text-shadow:0 2px 14px rgba(0,0,0,0.85);">' + T["scene_title"] + '</div>'
        '<div style="font-family:Georgia,serif;font-size:13px;'
        'color:rgba(180,165,130,0.72);margin-top:5px;'
        'text-shadow:0 1px 8px rgba(0,0,0,0.85);">' + T["app_caption"] + '</div>'
        '</div>'
    )
    return html + overlay
